class LinkedListQueue(
    // 头节点 front ，尾节点 rear
    private var front: ListNode? = null,
    private var rear: ListNode? = null,
    private var queSize: Int = 0
) {

    /* 获取队列的长度 */
    fun size(): Int {
        return queSize
    }

    /* 判断队列是否为空 */
    fun isEmpty(): Boolean {
        return size() == 0
    }

    /* 入队 */
    fun push(num: Int) {
        // 在尾节点后添加 num
        val node = ListNode(num)
        // 如果队列为空，则令头、尾节点都指向该节点
        if (front == null) {
            front = node
            rear = node
            // 如果队列不为空，则将该节点添加到尾节点后
        } else {
            rear?.next = node
            rear = node
        }
        queSize++
    }

    /* 出队 */
    fun pop(): Int {
        val num = peek()
        // 删除头节点
        front = front?.next
        queSize--
        return num
    }

    /* 访问队首元素 */
    fun peek(): Int {
        if (isEmpty()) throw IndexOutOfBoundsException()
        return front!!._val
