            rear = node
            // 如果队列不为空，则将该节点添加到尾节点后
        } else {
            rear?.next = node
            rear = node
        }
        queSize++
    }

    /* 出队 */
    fun pop(): Int {
        val num = peek()
        // 删除头节点
        front = front?.next
        queSize--
        return num
    }

