    }

    /* 入队 */
    public void Push(int num) {
        if (queSize == Capacity()) {
            Console.WriteLine("队列已满");
            return;
        }
        // 计算队尾指针，指向队尾索引 + 1
        // 通过取余操作实现 rear 越过数组尾部后回到头部
        int rear = (front + queSize) % Capacity();
        // 将 num 添加至队尾
        nums[rear] = num;
        queSize++;
    }

    /* 出队 */
    public int Pop() {
        int num = Peek();
        // 队首指针向后移动一位，若越过尾部，则返回到数组头部
        front = (front + 1) % Capacity();
        queSize--;
        return num;
    }

    /* 访问队首元素 */
    public int Peek() {
